cd /tmp && python3 << 'EOF'
import json
for f in ['alg.json','geo.json']:
    d = json.load(open(f))
    print('====',f)
    for q in d['questions']:
        counts={}
        for s in q['samples']:
            counts[s['answer']]=counts.get(s['answer'],0)+1
        maj = max(counts.items(), key=lambda x:x[1])
        gt = q['correct_answer']
        if maj[0]!=gt:
            gt_count = counts.get(gt,0)
            print(f"gt={gt!r} gt_count={gt_count} maj={maj} counts={counts}")
EOF
